// Runs the benchmark pipeline: refresh provider pricing, fetch Artificial Analysis
// data, update config/model-mapping.json, then score models. See README for how the
// mapping is maintained and how broken parsers are repaired locally.

import { fetchArtificialAnalysisData } from "./artificial-analysis/fetch.ts";
import { updateModelMapping } from "./mapping/update-mapping.ts";
import { refreshPricingSource } from "./pricing/refresh.ts";
import { pricingSources } from "./pricing/sources.ts";
import { computeScores } from "./scoring/compute-scores.ts";

const totalSteps = pricingSources.length + 3;
let step = 0;
const logStep = (label: string) =>
  console.log(`${step > 0 ? "\n" : ""}== Step ${++step}/${totalSteps}: ${label} ==`);

try {
  if (!process.env.AA_API_KEY) {
    console.error(
      "Missing AA_API_KEY. Locally, copy .env.example to .env and fill it in; in CI, set the AA_API_KEY repository secret.",
    );
    process.exit(1);
  }

  const failedSources: string[] = [];
  for (const source of pricingSources) {
    logStep(`refreshing ${source.displayName} pricing`);
    if (!(await refreshPricingSource(source))) failedSources.push(source.displayName);
  }

  logStep("fetching Artificial Analysis benchmark data");
  await fetchArtificialAnalysisData();

  logStep("updating model mapping");
  await updateModelMapping();

  logStep("scoring models per category");
  await computeScores();

  if (failedSources.length > 0) {
    console.error(
      `\nDone with parser failures (${failedSources.join(", ")}); some pricing data is stale or missing (see errors above).`,
    );
    process.exitCode = 1;
  } else {
    console.log("\nDone. See data/recommendations.json.");
  }
} catch (err) {
  console.error(err);
  process.exit(1);
}
import { mkdir, writeFile } from "node:fs/promises";
import path from "node:path";
import { downloadHtml } from "./downloader.ts";
import { repairParser } from "./repair-parser.ts";
import type { PricingSource } from "./source.ts";

// Returns false when parsing failed and could not be repaired (existing data file is left
// untouched). Network errors are not caught and abort the pipeline.
export async function refreshPricingSource<Row>(source: PricingSource<Row>): Promise<boolean> {
  const html = await downloadHtml(source.sourceUrl);

  let models: Row[];
  try {
    models = source.parse(html);
  } catch (error) {
    const repaired = await repairParser({ source, html, error });
    if (!repaired) return false;
    models = repaired;
  }

  await mkdir(path.dirname(source.outFile), { recursive: true });
  await writeFile(
    source.outFile,
    JSON.stringify(
      {
        sourceUrl: source.sourceUrl,
        fetchedAt: new Date().toISOString(),
        notes: source.notes,
        models,
      },
      null,
      2,
    ),
  );
  console.log(`Wrote ${models.length} ${source.displayName} models to ${source.outFile}`);
  return true;
}
export class NetworkError extends Error {
  url: string;
  status?: number;

  constructor(message: string, url: string, options?: { status?: number; cause?: unknown }) {
    super(message, { cause: options?.cause });
    this.name = "NetworkError";
    this.url = url;
    this.status = options?.status;
  }
}

export async function downloadHtml(url: string): Promise<string> {
  let res: Response;
  try {
    res = await fetch(url);
  } catch (err) {
    throw new NetworkError(`Request to ${url} failed: ${(err as Error).message}`, url, {
      cause: err,
    });
  }

  if (!res.ok) {
    const body = await res.text();
    throw new NetworkError(`${res.status} ${res.statusText} on ${url}: ${body}`, url, {
      status: res.status,
    });
  }
  return res.text();
}
